describe('JavaScript Confirm Dialog', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
  });

  it('should record the user choice when confirming a JavaScript dialog', () => {
    cy.get('[data-testid="confirm-button"]').click();
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-button"]').click();
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Ok');
    cy.get('[data-testid="result"]').should('have.class', 'success');
  });

  it('should record the user choice when dismissing a JavaScript dialog', () => {
    cy.get('[data-testid="confirm-button"]').click();
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-button"]').click();
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Cancel');
    cy.get('[data-testid="result"]').should('have.class', 'error');
  });
});
